insert into public.listings (id,kind,title,details) values
('c1','communities','The Weekend Wanderers','{"id":"c1","kind":"communities","title":"The Weekend Wanderers","subtitle":"Good trails. Better company.","city":"Bengaluru","area":"Bengaluru & beyond","image":"https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&w=800&q=85","tags":["Travel","Outdoors"],"category":"Travel","members":1248,"description":"For those who believe the best weekends start where the city ends. Join easygoing hikes, spontaneous getaways, and a lovely bunch of fellow explorers. All experience levels welcome."}'::jsonb),
('c2','communities','Bangalore Coffee Club','{"id":"c2","kind":"communities","title":"Bangalore Coffee Club","subtitle":"A little coffee. A lot of connection.","city":"Bengaluru","area":"Indiranagar, Bengaluru","image":"https://images.unsplash.com/photo-1442512595331-e89e73853f31?auto=format&fit=crop&w=800&q=85","tags":["Food & drink","Social"],"category":"Food & drink","members":856,"description":"Discover the city one cup at a time. We meet at independent cafés, share our favourite brews, and make room for new friendships. Our next coffee walk is this Sunday at 10 AM."}'::jsonb),
('c3','communities','Two Wheels, One Tribe','{"id":"c3","kind":"communities","title":"Two Wheels, One Tribe","subtitle":"Find your next riding crew.","city":"Bengaluru","area":"Bengaluru","image":"https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=800&q=85","tags":["Automobiles","Adventure"],"category":"Automobiles","members":632,"description":"Sunrise rides, winding roads, and people who get it. A welcoming motorcycle community with safety-first weekend rides, maintenance workshops, and shared stories."}'::jsonb),
('c4','communities','Through the Lens','{"id":"c4","kind":"communities","title":"Through the Lens","subtitle":"See your city a little differently.","city":"Mumbai","area":"Bandra, Mumbai","image":"https://images.unsplash.com/photo-1452587925148-ce544e77e70d?auto=format&fit=crop&w=800&q=85","tags":["Photography","Creative"],"category":"Photography","members":421,"description":"A space for curious photographers. Explore neighbourhoods on photo walks, exchange feedback, and learn together. Phone cameras are just as welcome as professional kits."}'::jsonb),
('p1','people','Aanya Sharma, 25','{"id":"p1","kind":"people","title":"Aanya Sharma, 25","subtitle":"Product designer · Looking for a flatmate","city":"Bengaluru","area":"Indiranagar, Bengaluru","image":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=85","tags":["Flatmates","Vegetarian","Early bird"],"category":"Flatmates","price":15000,"match":96,"description":"Moving to Indiranagar and looking for a friendly, tidy flatmate. I love cooking, quiet weekday evenings, and hiking on the weekends. Budget ₹15,000 per month. Available from December."}'::jsonb),
('p2','people','Rohan Mehta, 28','{"id":"p2","kind":"people","title":"Rohan Mehta, 28","subtitle":"Software engineer · Travel partner","city":"Bengaluru","area":"Koramangala, Bengaluru","image":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=800&q=85","tags":["Travel partners","Backpacking","Photography"],"category":"Travel partners","price":20000,"match":92,"description":"Planning a week in the mountains this December. Looking for travel buddies who enjoy slow travel, street food, and a good sunrise. Flexible dates and a ₹20,000 trip budget."}'::jsonb),
('p3','people','Meera Kapoor, 26','{"id":"p3","kind":"people","title":"Meera Kapoor, 26","subtitle":"Architect · Looking for a flatmate","city":"Mumbai","area":"Bandra, Mumbai","image":"https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=800&q=85","tags":["Flatmates","Pet friendly","Creative"],"category":"Flatmates","price":25000,"match":89,"description":"Looking for a creative, easygoing flatmate in Bandra. My cat and I are happy to share a bright space with someone who appreciates a clean home and good music."}'::jsonb),
('s1','places','A little space to call yours','{"id":"s1","kind":"places","title":"A little space to call yours","subtitle":"Private room in a shared apartment","city":"Bengaluru","area":"Indiranagar, Bengaluru","image":"https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=85","tags":["Shared living","Furnished","Wi-Fi"],"category":"Stays","price":14500,"description":"A sunny, fully furnished room in a spacious 3-bedroom apartment. Includes Wi-Fi, washing machine, a shared kitchen, and a balcony with leafy views. One month deposit. Utilities charged separately."}'::jsonb),
('s2','places','Your next mountain escape','{"id":"s2","kind":"places","title":"Your next mountain escape","subtitle":"Boutique hostel · Mountain view","city":"Manali","area":"Old Manali, Himachal Pradesh","image":"https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=800&q=85","tags":["Stays","Backpacker friendly"],"category":"Stays","price":850,"description":"Wake up to mountain views at this social hostel in Old Manali. Shared dorms, a cosy common room, fast Wi-Fi, and an in-house café. Price per person per night."}'::jsonb),
('s3','places','Take the scenic route','{"id":"s3","kind":"places","title":"Take the scenic route","subtitle":"Royal Enfield Classic 350 rental","city":"Bengaluru","area":"HSR Layout, Bengaluru","image":"https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=800&q=85","tags":["Vehicle rentals","Helmet included"],"category":"Rentals","price":1200,"description":"A well-maintained Classic 350 for your next adventure. Helmet included. Valid licence and refundable security deposit required. Price per day; fuel is extra."}'::jsonb),
('e1','events','Sunrise at Nandi Hills','{"id":"e1","kind":"events","title":"Sunrise at Nandi Hills","subtitle":"A small hike. A big breath of fresh air.","city":"Bengaluru","area":"Nandi Hills, Bengaluru","image":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=85","tags":["Outdoors","Travel"],"category":"Travel","price":799,"members":24,"date":"2026-11-28","description":"An early-morning hike with The Weekend Wanderers. Meet at Hebbal at 4:30 AM. Includes group transport, a local guide, and breakfast. Bring comfortable shoes, water, and a light jacket."}'::jsonb),
('e2','events','Coffee & Conversations','{"id":"e2","kind":"events","title":"Coffee & Conversations","subtitle":"Your Sunday, with a new circle.","city":"Bengaluru","area":"Third Wave, Indiranagar","image":"https://images.unsplash.com/photo-1521017432531-fbd92d768814?auto=format&fit=crop&w=800&q=85","tags":["Food & drink","Social"],"category":"Food & drink","price":350,"members":18,"date":"2026-11-29","description":"An easy Sunday meetup for people new to the city and those looking to grow their circle. Starts at 10 AM. Your ticket includes one coffee. Limited to 30 people."}'::jsonb),
('e3','events','Golden Hour Photowalk','{"id":"e3","kind":"events","title":"Golden Hour Photowalk","subtitle":"Chase the light, together.","city":"Mumbai","area":"Bandra Fort, Mumbai","image":"https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=800&q=85","tags":["Photography","Creative"],"category":"Photography","price":0,"members":16,"date":"2026-12-05","description":"A free, beginner-friendly photowalk around Bandra Fort. Meet at 4 PM with any camera or phone. We will share photos and tips over chai afterwards."}'::jsonb)
